package lab.commerceflow.storefront.service;
import lab.commerceflow.storefront.domain.*;import lab.commerceflow.storefront.mapper.*;import lab.commerceflow.storefront.web.dto.*;import java.util.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class MerchantFulfillmentService{private final MerchantOrderMapper merchants;private final ShopOrderMapper orders;public MerchantFulfillmentService(MerchantOrderMapper merchants,ShopOrderMapper orders){this.merchants=merchants;this.orders=orders;}public List<MerchantOrderResponse> list(AppUser merchant){return merchants.list(merchant.getId()).stream().map(this::response).toList();}@Transactional public MerchantOrderResponse confirm(AppUser merchant,Long id){ShopOrderView order=require(merchant,id);if(merchants.confirm(id)!=1)throw new BusinessRuleException("Only paid orders can be confirmed");orders.insertEvent(id,merchant.getId(),"MERCHANT_CONFIRMED","PAID","CONFIRMED","Merchant accepted the order");return response(merchants.lock(merchant.getId(),id).orElseThrow());}@Transactional public MerchantOrderResponse ship(AppUser merchant,Long id,FulfillmentRequest request){ShopOrderView order=require(merchant,id);if(merchants.ship(id,request.carrier(),request.trackingNumber())!=1)throw new BusinessRuleException("Only confirmed orders can be shipped");orders.insertEvent(id,merchant.getId(),"ORDER_SHIPPED","CONFIRMED","SHIPPED",request.carrier()+" / "+request.trackingNumber());return response(merchants.lock(merchant.getId(),id).orElseThrow());}private ShopOrderView require(AppUser merchant,Long id){return merchants.lock(merchant.getId(),id).orElseThrow(()->new ResourceNotFoundException("Merchant order not found"));}private MerchantOrderResponse response(ShopOrderView order){return new MerchantOrderResponse(order.getId(),order.getOrderNumber(),order.getStatus(),order.getTotalAmount(),order.getCurrency(),order.getCreatedAt(),orders.items(order.getId()).stream().map(ShopOrderResponse.Item::from).toList(),ShopOrderResponse.Address.from(orders.address(order.getId())));}}
